<!DOCTYPE html>
<html lang="id"><head><meta charset="UTF-8"><title>Detail {{ $application->name }}</title><style>body{font-family:DejaVu Sans,Arial,sans-serif;color:#263238;font-size:12px}h1{color:#087f75;font-size:24px;margin-bottom:4px}h2{font-size:15px;background:#087f75;color:#fff;padding:9px;margin:22px 0 0}p{color:#71808a;margin-top:4px}.meta{color:#087f75;font-weight:bold}.grid{display:grid;grid-template-columns:1fr 1fr;border:1px solid #dfe4e7;border-top:0}.item{padding:10px;border-bottom:1px solid #dfe4e7}.item:nth-child(odd){border-right:1px solid #dfe4e7}.label{display:block;color:#71808a;font-size:10px;text-transform:uppercase;margin-bottom:4px}.full{grid-column:1/-1}.footer{margin-top:28px;border-top:1px solid #dfe4e7;padding-top:10px;color:#71808a;font-size:10px}</style></head><body><h1>{{ $application->name }}</h1><div class="meta">{{ $application->code }} | {{ $application->status }}</div><p>Detail katalog aplikasi DIBA</p><h2>Informasi aplikasi</h2><div class="grid">@foreach([['Pemilik', $application->owner],['Layanan', $application->service],['Tahun pembuatan', $application->year],['Sektor', $application->sector],['Bahasa pemrograman', $application->language],['Framework', $application->framework],['Database', $application->database],['Operating system', $application->operating_system],['Server', $application->server],['Biaya pembangunan', 'Rp '.number_format((float) $application->development_cost, 0, ',', '.')],['URL', $application->url],['Deskripsi', $application->description],['Unit operasional', $application->operational_unit],['Aplikasi terintegrasi', $application->integrations]] as [$label, $value])<div class="item {{ in_array($label, ['Deskripsi','Unit operasional','Aplikasi terintegrasi']) ? 'full' : '' }}"><span class="label">{{ $label }}</span>{{ $value ?: '-' }}</div>@endforeach</div><div class="footer">Dicetak dari DIBA Katalog Aplikasi Jawa Barat pada {{ now()->format('d-m-Y H:i') }}</div></body></html>
